//! Rimelight design tokens for Rust and Slint.
//!
//! This crate is a thin wrapper around generated data. Two files are generated by
//! `packages/design/generate.ts` from `packages/design/tokens.json` (see `SCHEMA.md`):
//!
//! - `src/generated.rs`: the `Rgba` type, the `tokens` module of constants and the `ROLES` table.
//! - `ui/tokens.slint`: the `Tokens` global and the `ThemeChoice` enum for Slint apps.
//!
//! Do not edit the generated files by hand. Change `tokens.json` and run `node generate.ts`.

#![forbid(unsafe_code)]

mod generated;

pub use generated::*;

/// Absolute path of the directory that holds the generated Slint files (`tokens.slint`).
pub const UI_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/ui");

#[cfg(test)]
mod tests {
    use super::tokens;
    use std::collections::HashSet;

    #[test]
    fn roles_is_not_empty() {
        assert!(!tokens::ROLES.is_empty());
    }

    #[test]
    fn role_names_are_unique() {
        let mut seen = HashSet::new();
        for (name, _, _) in tokens::ROLES {
            assert!(seen.insert(*name), "duplicate role name {name}");
        }
    }

    #[test]
    fn text_primary_differs_from_surface_base_in_both_themes() {
        assert_ne!(
            tokens::color::light::TEXT_PRIMARY,
            tokens::color::light::SURFACE_BASE
        );
        assert_ne!(
            tokens::color::dark::TEXT_PRIMARY,
            tokens::color::dark::SURFACE_BASE
        );
    }
}
